@js:(() => {
  const j = JSON.parse(result);
  const id = (j.metadata && j.metadata.identifier) || lastResult;
  const files = (j.files || []).filter((f) => /\.(mp4|m4v|webm|ogv)$/i.test(f.name));
  // 优先原始文件，其次转码文件
  files.sort((a, b) => (/(\.ia|_512kb)(?=\.(mp4|m4v|webm|ogv)$)/i.test(a.name) ? 1 : 0) - (/(\.ia|_512kb)(?=\.(mp4|m4v|webm|ogv)$)/i.test(b.name) ? 1 : 0));
  const seen = new Set();
  const list = [];
  for (const f of files) {
    const key = f.name.replace(/(\.ia|_512kb)(?=\.(mp4|m4v|webm|ogv)$)/i, '').replace(/\.(mp4|m4v|webm|ogv)$/i, '');
    if (seen.has(key)) continue;
    seen.add(key);
    list.push({
      name: f.title || f.name.replace(/^.*\//, '').replace(/\.(mp4|m4v|webm|ogv)$/i, ''),
      url: 'https://archive.org/download/' + id + '/' + f.name.split('/').map(encodeURIComponent).join('/')
    });
  }
  list.sort((a, b) => a.url.localeCompare(b.url, undefined, { numeric: true }));
  return list;
})()

