  const $ = cheerio.load(result);
  const out = [];
  $('h2').each((i, el) => {
    const name = $(el).text().replace(/\s+/g, ' ').trim();
    if (name) out.push({ name, url: baseUrl + '#we-' + i });
  });
  if (!out.length) out.push({ name: '正文', url: baseUrl + '#we-all' });
