@js:(() => {
  const $ = cheerio.load(result);
  $('script,style').remove();
  const m = /#we-(\w+)$/.exec(lastResult);
  const idx = m ? m[1] : 'all';
  let $nodes;
  if (idx === 'all') $nodes = $('body').find('p');
  else {
    const h = $('h2').eq(Number(idx));
    $nodes = h.nextUntil('h2');
  }
  const out = [];
  $nodes.each((_, el) => {
    const $el = $(el);
    const ps = $el.is('p') ? $el : $el.find('p');
    if (ps.length) ps.each((__, p) => out.push($(p).text().replace(/\s+/g, ' ').trim()));
    else out.push($el.text().replace(/\s+/g, ' ').trim());
  });
  return out.filter(Boolean);
})()
